const ORDEN=['Premium','Partmo','Fleetguard','Baldwin','Donaldson','Fram','Franig','Mann','Sakura','Wix','Mahle','Wega','Luber-finer','Purolator','Hengst','Napa','Millard','Gonher','Premium Guard','Hifi Filter','Elemfil','OEM'];
const GR=['fa','fi','fc','fw'];
const norm=s=>String(s).toUpperCase().replace(/[^A-Z0-9]/g,'');
let IDX=null,ROW=null,HUBP=null;
function tokens(name){const raw=String(name).toUpperCase().split(/[\s,;():]+/).filter(Boolean),o=[];
 raw.forEach((t,i)=>{o.push(t);const n=raw[i+1];if(n&&/[A-Z]/.test(t)&&t.length<=4&&/\d/.test(n))o.push(t+n);if(/[-\/]/.test(t))t.split(/[-\/]/).forEach(q=>q&&o.push(q))});return o}
function ok(n){if(/^\d+$/.test(n))return n.length>=5;return /\d/.test(n)&&/[A-Z]/.test(n)&&n.length>=3}
function build(){if(IDX)return;IDX={};ROW={};HUBP={};
 for(const h in EQ_DATA){const d=EQ_DATA[h];for(const b in d)d[b].forEach(c=>{const n=norm(c);if(n.length<2)return;(IDX[n]=IDX[n]||new Set()).add(h)})}
 (typeof P!=='undefined'?P:[]).forEach(p=>{if(!GR.includes(p.c))return;const hs=new Set();tokens(p.n).forEach(t=>{const n=norm(t);if(ok(n)&&IDX[n])IDX[n].forEach(h=>hs.add(h))});
  if(hs.size){ROW[p.id]=[...hs].slice(0,5);ROW[p.id].forEach(h=>(HUBP[h]=HUBP[h]||[]).push(p.id))}})}
function porMarca(hubs){const m={};hubs.forEach(h=>{const d=EQ_DATA[h];for(const b in d){m[b]=m[b]||new Map();d[b].forEach(c=>{const n=norm(c);if(!m[b].has(n)||c.length<m[b].get(n).length)m[b].set(n,c)})}});
 const L=b=>[b,[...m[b].values()]];return ORDEN.filter(b=>m[b]).map(L).concat(Object.keys(m).filter(b=>!ORDEN.includes(b)).map(L))}
function hubsDeCodigo(q){build();const hs=new Set();const t=String(q).trim();if(!t)return[];
 const cand=new Set([norm(t)]);t.split(/\s+/).forEach(w=>cand.add(norm(w)));tokens(t).forEach(w=>cand.add(norm(w)));
 cand.forEach(n=>{if(n&&ok(n)&&IDX[n])IDX[n].forEach(h=>hs.add(h))});return[...hs].slice(0,6)}
function productosDe(hubs,excl){const ids=new Set();hubs.forEach(h=>(HUBP[h]||[]).forEach(i=>{if(i!==excl)ids.add(i)}));
 return[...ids].map(i=>P[i]).sort((a,b)=>(b.st?1:0)-(a.st?1:0)||a.p-b.p)}
const esc2=s=>typeof esc==='function'?esc(s):String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const WA='https://wa.me/573125529044?text=';
function tablaHTML(hubs,limite){const f=porMarca(hubs);return`<div class="eqt">${f.map(([b,cs])=>`<div class="eqr"><b>${esc2(b)}</b><span>${cs.slice(0,limite||10).map(c=>`<code>${esc2(c)}</code>`).join(' ')}${cs.length>(limite||10)?` <em>+${cs.length-(limite||10)} más</em>`:''}</span></div>`).join('')}</div>`}
function miniProd(p){return`<div class="eqp"><div><b>${esc2(p.n)}</b><small>${p.st?'Disponible':'Consultar disponibilidad'}</small></div><span>${money(pr(p.p))}</span><button class="btn blue" data-add="${p.id}">Agregar</button></div>`}
function abrir(id){build();const p=P[id];if(!p)return;const hubs=ROW[id]||[];const m=document.createElement('div');m.className='modal';document.body.append(m);const cerrar=()=>m.remove();
 let h=`<div class="tk eqm" role="dialog" aria-modal="true" aria-label="Equivalencias"><h3>Equivalencias</h3><p class="eqn"><b>${esc2(p.n)}</b></p>`;
 if(hubs.length){const otros=productosDe(hubs,id);
  h+=`<p class="eqs">Estas referencias de otras marcas cumplen la misma función. Verifica siempre con tu placa o el filtro viejo antes de comprar.</p>${tablaHTML(hubs,14)}`;
  h+=otros.length?`<h4 class="eqh">También tenemos en el local</h4>${otros.slice(0,10).map(miniProd).join('')}`:`<p class="eqs">No tenemos otra marca equivalente cargada en la tienda; pregúntanos por WhatsApp.</p>`}
 else h+=`<p class="eqs">Aún no tenemos publicado el cruce de esta referencia. Escríbenos y la verificamos contra el catálogo del fabricante.</p>`;
 h+=`<div class="cta" style="margin:16px 0 0"><a class="btn red" target="_blank" rel="noopener" href="${WA+encodeURIComponent('Hola Multiservicios JRG, quiero verificar la equivalencia del filtro: '+p.n)}">Consultar por WhatsApp</a><button class="chip" id="eqx">Cerrar</button></div></div>`;
 m.innerHTML=h;m.querySelector('#eqx').onclick=cerrar;m.onclick=e=>{if(e.target===m)cerrar()};document.addEventListener('keydown',function k(e){if(e.key==='Escape'){cerrar();document.removeEventListener('keydown',k)}})}
/* Botón en las tarjetas de filtros */
const base=window.cardHTML;
if(typeof base==='function'){window.cardHTML=function(p){let h=base(p);if(GR.includes(p.c)){build();const t=ROW[p.id]?'Ver equivalencias':'Consultar equivalencia';h=h.replace('<button class="btn blue" data-add','<button class="btn ghost eqb" data-eq="'+p.id+'">'+t+'</button><button class="btn blue" data-add')}return h}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-eq]');if(b)abrir(+b.dataset.eq)});
/* Buscar por código de otra marca en la tienda */
function panel(){const q=(document.getElementById('pq')||{}).value||'';let el=document.getElementById('eqres');
 const hubs=q.trim().length>=3?hubsDeCodigo(q):[];
 if(!hubs.length){if(el)el.remove();return}
 const prods=productosDe(hubs).slice(0,6);
 if(!el){el=document.createElement('div');el.id='eqres';document.getElementById('pgrid').before(el)}
 el.innerHTML=`<h3>Equivalencias de “${esc2(q.trim())}”</h3><p>Referencias de otras marcas que cumplen la misma función:</p>${tablaHTML(hubs,10)}${prods.length?`<p><b>Productos nuestros equivalentes</b></p><div class="grid">${prods.map(p=>window.cardHTML(p)).join('')}</div>`:`<p>No tenemos ese cruce cargado en la tienda todavía; <a class="lnk" target="_blank" rel="noopener" href="${WA+encodeURIComponent('Hola Multiservicios JRG, busco la equivalencia de '+q.trim())}">escríbenos por WhatsApp</a>.</p>`}`}
